/* Editorial Layout */
.editorial-layout {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: var(--spacing-xxl);
    align-items: center;
}

.editorial-image-wrapper {
    border-radius: var(--border-radius);
