}

.form-group {
    flex-grow: 1;
    min-width: 250px;
}

input[type="email"] {
    width: 100%;
    padding: var(--spacing-sm) var(--spacing-md);
    border: 1px solid transparent;
    border-radius: var(--border-radius);
    font-size: 1rem;
    font-family: inherit;
    height: 100%;
