    // Mobile Menu Toggle
    const menuToggle = document.querySelector('.menu-toggle');
    const mainNav = document.getElementById('main-nav');

    if (menuToggle && mainNav) {
        menuToggle.addEventListener('click', () => {
            const isExpanded = menuToggle.getAttribute('aria-expanded') === 'true';
            menuToggle.setAttribute('aria-expanded', !isExpanded);
            mainNav.classList.toggle('is-open');
        });
    }

    // Quick Add to Cart (Simulated)
    const quickAddButtons = document.querySelectorAll('.quick-add');
    const cartBadge = document.querySelector('.cart-badge');
    let cartCount = 0;

    function updateCart(message) {
        cartCount++;
        if (cartBadge) {
            cartBadge.textContent = cartCount;
            const cartButton = cartBadge.closest('button');
            if (cartButton) {
                cartButton.setAttribute('aria-label', `Shopping Cart, ${cartCount} items`);
            }
        }
        announceToScreenReader(message);
    }

    quickAddButtons.forEach(button => {
        button.addEventListener('click', (e) => {
            e.preventDefault();
            updateCart('Item added to cart');
        });
    });

    const addButtons = document.querySelectorAll('.deal-content .button');
    addButtons.forEach(button => {
        button.addEventListener('click', (e) => {
            e.preventDefault();
            updateCart('Deal item added to cart');
        });
    });

    // Newsletter Form Submission
    const newsletterForm = document.getElementById('newsletter-form');
    const emailInput = document.getElementById('email');
    const messageDiv = document.getElementById('newsletter-message');

    if (newsletterForm) {
        newsletterForm.addEventListener('submit', (e) => {
            e.preventDefault();
            const email = emailInput.value.trim();

            // Basic validation
            if (!email || !email.includes('@')) {
                emailInput.setAttribute('aria-invalid', 'true');
                showMessage('Please enter a valid email address.', 'error');
                emailInput.focus();
                return;
            }

            emailInput.removeAttribute('aria-invalid');

            // Simulate API call
            const submitBtn = newsletterForm.querySelector('button[type="submit"]');
            const originalText = submitBtn.textContent;
            submitBtn.textContent = 'Subscribing...';
            submitBtn.disabled = true;

            setTimeout(() => {
                showMessage('Thank you for subscribing!', 'success');
                newsletterForm.reset();
                submitBtn.textContent = originalText;
                submitBtn.disabled = false;
            }, 1000);
        });
    }

    function showMessage(msg, type) {
        messageDiv.textContent = msg;
        messageDiv.className = 'newsletter-message ' + type;
    }

    function announceToScreenReader(message) {
        let announcer = document.getElementById('sr-announcer');
        if (!announcer) {
            announcer = document.createElement('div');
            announcer.id = 'sr-announcer';
            announcer.className = 'visually-hidden';
            announcer.setAttribute('aria-live', 'polite');
            document.body.appendChild(announcer);
        }
        announcer.textContent = '';
        setTimeout(() => {
            announcer.textContent = message;
        }, 50);
    }

    // Timer simulation for Deals
    const timerElements = document.querySelectorAll('.timer');
    timerElements.forEach(timerEl => {
        let timeStr = timerEl.textContent;
        let [hours, minutes, seconds] = timeStr.split(':').map(Number);

        let totalSeconds = (hours * 3600) + (minutes * 60) + seconds;

        const interval = setInterval(() => {
            if (totalSeconds <= 0) {
                clearInterval(interval);
                timerEl.textContent = "Expired";
                return;
            }

            totalSeconds--;

            const h = Math.floor(totalSeconds / 3600);
            const m = Math.floor((totalSeconds % 3600) / 60);
            const s = totalSeconds % 60;

            timerEl.textContent = `${h.toString().padStart(2, '0')}:${m.toString().padStart(2, '0')}:${s.toString().padStart(2, '0')}`;
        }, 1000);
    });
