    font-family: var(--font-family-heading);
    font-weight: 700;
    line-height: 1.2;
}

p {
    margin-top: 0;
    margin-bottom: var(--spacing-md);
}

a {
    color: inherit;
    text-decoration: none;
}

a:hover, a:focus {
    text-decoration: underline;
}

img, svg {
    max-width: 100%;
    height: auto;
    display: block;
}

button {
    cursor: pointer;
    font-family: inherit;
}

/* Accessibility */
.skip-link {
    position: absolute;
    top: -40px;
    left: 0;
    background: var(--color-primary);
    color: var(--color-primary-text);
    padding: var(--spacing-sm) var(--spacing-md);
    z-index: 1000;
    transition: top 0.2s;
}

.skip-link:focus {
    top: 0;
    outline: 2px solid var(--color-focus);
    outline-offset: 2px;
}

.visually-hidden {
    position: absolute !important;
    width: 1px !important;
    height: 1px !important;
    padding: 0 !important;
    margin: -1px !important;
    overflow: hidden !important;
    clip: rect(0, 0, 0, 0) !important;
    white-space: nowrap !important;
    border: 0 !important;
}

:focus-visible {
    outline: 3px solid var(--color-focus);
    outline-offset: 2px;
}

/* Layout */
.container {
    width: 100%;
    max-width: 1200px;
    margin: 0 auto;
    padding: 0 var(--spacing-md);
}

.section {
    padding: var(--spacing-xxl) 0;
}

.section-alt {
    background-color: var(--color-bg-alt);
}

/* Header */
.site-header {
    border-bottom: 1px solid var(--color-border);
    padding: var(--spacing-md) 0;
    background: var(--color-bg);
    position: sticky;
    top: 0;
    z-index: 100;
}

.header-container {
    display: flex;
    align-items: center;
    justify-content: space-between;
    flex-wrap: wrap;
}

.logo {
    display: flex;
    align-items: center;
    gap: var(--spacing-sm);
    font-weight: 700;
    font-size: 1.25rem;
    text-decoration: none !important;
}

.menu-toggle {
    display: none;
    background: transparent;
    border: none;
    padding: var(--spacing-sm);
    color: var(--color-text);
}

.main-nav .nav-list {
    list-style: none;
    margin: 0;
    padding: 0;
    display: flex;
    gap: var(--spacing-lg);
}

.nav-list a {
    font-weight: 500;
    text-decoration: none;
}

.nav-list a:hover, .nav-list a:focus {
    text-decoration: underline;
}

.header-actions {
    display: flex;
    align-items: center;
    gap: var(--spacing-sm);
}

.icon-button {
    background: transparent;
    border: none;
    padding: var(--spacing-sm);
    color: var(--color-text);
    position: relative;
    border-radius: var(--border-radius);
}

.icon-button:hover {
    background-color: var(--color-bg-alt);
}

.cart-badge {
    position: absolute;
    top: 0;
    right: 0;
    background-color: var(--color-primary);
    color: var(--color-primary-text);
    font-size: 0.75rem;
    font-weight: bold;
    border-radius: 50%;
    min-width: 18px;
    height: 18px;
    display: flex;
    align-items: center;
    justify-content: center;
    padding: 0 4px;
}

/* Buttons */
.button {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    padding: var(--spacing-sm) var(--spacing-lg);
    font-weight: 600;
    border-radius: var(--border-radius);
    text-decoration: none !important;
    border: 1px solid transparent;
    transition: var(--transition);
}

.button-primary {
    background-color: var(--color-primary);
    color: var(--color-primary-text);
}

.button-primary:hover, .button-primary:focus {
    background-color: var(--color-primary-hover);
}

.button-secondary {
    background-color: var(--color-secondary);
    color: var(--color-secondary-text);
}

.button-secondary:hover, .button-secondary:focus {
    background-color: var(--color-secondary-hover);
}

.button-outline {
    background-color: transparent;
    border-color: var(--color-primary);
    color: var(--color-primary);
}

.button-outline:hover, .button-outline:focus {
    background-color: var(--color-primary);
    color: var(--color-primary-text);
}

.button-icon {
    display: flex;
    align-items: center;
    justify-content: center;
    width: 40px;
    height: 40px;
    border-radius: 50%;
    background-color: var(--color-bg);
    border: 1px solid var(--color-border);
    color: var(--color-text);
    transition: var(--transition);
}

.button-icon:hover, .button-icon:focus {
    background-color: var(--color-primary);
    color: var(--color-primary-text);
    border-color: var(--color-primary);
}

/* Hero Section */
.hero {
    background-color: var(--color-bg-alt);
    padding: var(--spacing-xl) 0;
}

.hero-container {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: var(--spacing-xxl);
    align-items: center;
}

.hero-content h1 {
    font-size: 3rem;
    margin-bottom: var(--spacing-md);
}

.hero-content p {
    font-size: 1.25rem;
    color: var(--color-text-muted);
    margin-bottom: var(--spacing-xl);
}

.hero-image-wrapper {
    border-radius: var(--border-radius);
    overflow: hidden;
}

.hero-image {
    width: 100%;
    object-fit: cover;
    aspect-ratio: 4 / 5;
}

/* Sections Common */
.section-header {
    display: flex;
    justify-content: space-between;
    align-items: flex-end;
    margin-bottom: var(--spacing-xl);
    flex-wrap: wrap;
    gap: var(--spacing-md);
}

.section-header h2 {
    margin-bottom: 0;
    font-size: 2rem;
}

.section-desc {
    width: 100%;
    color: var(--color-text-muted);
    margin-bottom: 0;
    margin-top: var(--spacing-sm);
    font-size: 1.1rem;
}

.link-action {
    font-weight: 600;
    display: inline-flex;
    align-items: center;
    gap: var(--spacing-xs);
}

/* Product Grid */
.grid {
