    .main-nav .nav-list {
        flex-direction: column;
        gap: var(--spacing-md);
    }
}

@media (max-width: 576px) {
    .footer-grid {
        grid-template-columns: 1fr;
    }

    .footer-bottom {
        flex-direction: column;
        text-align: center;
    }
}

/* Reflow SC 1.4.10 */
@media (max-width: 320px) {
    .product-grid {
